/**
 * Tests for stop/security-scan-aggregator (#3705).
 *
 * The #905 fix was inert: sync scans inside Promise executors ran sequentially
 * and the timers could never fire. These tests pin the three NEW behaviors that
 * make the rewrite real: the clean-tree gate, the machine-wide lock, and the
 * bounded secret scan actually producing results when the tree is dirty.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync, existsSync, readFileSync, unlinkSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { securityScanAggregator } from '../../stop/security-scan-aggregator.js';
import type { HookInput } from '../../types.js';

const LOCK_PATH = join(tmpdir(), 'ork-security-scan.lock');

describe('security-scan-aggregator (#3705)', () => {
  let tmpDir: string;

  function isolatedGitEnv() {
    return {
      ...process.env,
      HOME: tmpDir,
      GIT_CONFIG_GLOBAL: '/dev/null',
      GIT_CONFIG_SYSTEM: '/dev/null',
      GIT_DIR: join(tmpDir, '.git'),
      GIT_WORK_TREE: tmpDir,
    };
  }

  function git(cmd: string) {
    execSync(`git -c commit.gpgsign=false ${cmd}`, {
      cwd: tmpDir,
      stdio: 'pipe',
      env: isolatedGitEnv(),
    });
  }

  function hookInput(): HookInput {
    return {
      tool_name: '',
      session_id: 'test',
      tool_input: {},
      project_dir: tmpDir,
    } as HookInput;
  }

  const resultsDir = () => join(tmpDir, '.claude', 'hooks', 'logs', 'security');

  beforeEach(() => {
    tmpDir = mkdtempSync(join(tmpdir(), 'sec-scan-test-'));
    git('init -q');
    git('config user.email "test@test.local"');
    git('config user.name "Test"');
    try {
      unlinkSync(LOCK_PATH);
    } catch {
      // no stale lock to clear
    }
  });

  afterEach(() => {
    rmSync(tmpDir, { recursive: true, force: true });
    try {
      unlinkSync(LOCK_PATH);
    } catch {
      // lock already released
    }
  });

  it('skips entirely on a clean working tree', async () => {
    writeFileSync(join(tmpDir, 'a.txt'), 'hello');
    git('add .');
    git('commit -qm init');

    const result = await securityScanAggregator(hookInput());

    expect(result.continue).not.toBe(false);
    expect(existsSync(resultsDir())).toBe(false);
  });

  it('scans a dirty tree and writes an aggregated report', async () => {
    writeFileSync(join(tmpDir, 'config.ts'), 'const api_key = "abcdefgh12345678";\n');

    await securityScanAggregator(hookInput());

    const reportPath = join(resultsDir(), 'aggregated-report.json');
    expect(existsSync(reportPath)).toBe(true);
    const secrets = JSON.parse(readFileSync(join(resultsDir(), 'secrets.json'), 'utf8'));
    expect(secrets.count).toBe(1);
    expect(secrets.findings[0].file).toContain('config.ts');
  });

  it('skips when another live process holds the lock', async () => {
    writeFileSync(join(tmpDir, 'dirty.ts'), 'const x = 1;\n');
    // This test process is alive, so a lock bearing its pid is held-and-live.
    writeFileSync(LOCK_PATH, String(process.pid));

    const result = await securityScanAggregator(hookInput());

    expect(result.continue).not.toBe(false);
    expect(existsSync(resultsDir())).toBe(false);
    // The lock belongs to the fake holder and must survive the skip.
    expect(readFileSync(LOCK_PATH, 'utf8')).toBe(String(process.pid));
  });

  it('steals a lock left by a dead process and releases it after scanning', async () => {
    writeFileSync(join(tmpDir, 'dirty.ts'), 'const x = 1;\n');
    // A pid far beyond the OS pid range cannot be alive, so the lock
    // reads as abandoned.
    writeFileSync(LOCK_PATH, '999999999');

    await securityScanAggregator(hookInput());

    expect(existsSync(join(resultsDir(), 'aggregated-report.json'))).toBe(true);
    expect(existsSync(LOCK_PATH)).toBe(false);
  });
});
